// Aggregate Jobs v8 — tier-aware ordering
// Changes vs v7:
//   - Sort key is (source_tier ASC, updated_at DESC) instead of pure recency
//   - Tier 4 entries (clearly not real job pages) are dropped
//   - Result count in `tier_counts` for downstream display

const allJobs = [];
const seen = new Set();
const sourceCounts = {};

for (const item of $input.all()) {
  const jobs = item.json.jobs || [];
  const source = item.json.source || 'unknown';
  sourceCounts[source] = (sourceCounts[source] || 0) + jobs.length;
  for (const job of jobs) {
    if (!job || !job.url) continue;
    const dedupKey = job.url.replace(/[?#].*$/, '').replace(/\/+$/, '').toLowerCase();
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);
    allJobs.push(job);
  }
}

const expandCtx = $('Parse Expand Query').first().json;
const roleFamilies    = expandCtx.role_families    || [];
const excludedRoles   = expandCtx.excluded_roles   || [];
const locationCanon   = (expandCtx.location_canonical || '').trim().toLowerCase();
const remotePref      = expandCtx.remote_preference  || 'open';
const freshness       = expandCtx.freshness          || 'qdr:w';

const freshnessMs = { 'qdr:h': 3600000, 'qdr:d': 86400000, 'qdr:w': 604800000, 'qdr:m': 2592000000, 'qdr:y': 31536000000 }[freshness] || 604800000;
const cutoff = Date.now() - freshnessMs;

let filtered = allJobs;

// Drop Tier 4 (unknown / probably not a job page) outright
filtered = filtered.filter(j => (j.source_tier || 4) < 4);

// Role family filter
if (roleFamilies.length > 0) {
  filtered = filtered.filter(j => {
    const haystack = (j.title + ' ' + (j.department || '')).toLowerCase();
    if (excludedRoles.some(excl => {
      const terms = excl.toLowerCase().split(/\s+/);
      return terms.every(t => new RegExp('\\b' + t + '\\b').test(haystack));
    })) return false;
    return roleFamilies.some(variant => {
      const terms = variant.toLowerCase().split(/\s+/).filter(t => t.length > 1);
      return terms.every(term => term.length <= 3
        ? new RegExp('\\b' + term + '\\b').test(haystack)
        : haystack.includes(term));
    });
  });
}

// Location filter (hard, only when set and not remote_only)
if (remotePref !== 'remote_only' && locationCanon && !['any','anywhere','worldwide'].includes(locationCanon)) {
  const locTerms = locationCanon.split(/[\s,]+/).filter(t => t.length > 1);
  filtered = filtered.filter(j => {
    const src = (j.source || '').toLowerCase();
    if (src.includes('firecrawl') || src.includes('serper') || src.includes('youcom')) return true;
    const hay = (j.location || '').toLowerCase();
    if (!hay || hay === 'unknown') return true;
    return locTerms.some(t => hay.includes(t));
  });
}

// Recency filter (soft)
filtered = filtered.filter(j => {
  if (!j.updated_at) return true;
  const t = new Date(j.updated_at).getTime();
  return isNaN(t) || t >= cutoff;
});

// Sort: tier first (Tier 1 ATS at top), then recency within tier
filtered.sort((a, b) => {
  const tierDiff = (a.source_tier || 99) - (b.source_tier || 99);
  if (tierDiff !== 0) return tierDiff;
  const ad = new Date(a.updated_at || 0).getTime() || 0;
  const bd = new Date(b.updated_at || 0).getTime() || 0;
  return bd - ad;
});

// Tier composition for downstream display
const tierCounts = { 1: 0, 2: 0, '2.5': 0, 3: 0 };
for (const j of filtered) {
  const t = j.source_tier;
  if (t === 1) tierCounts[1]++;
  else if (t === 2) tierCounts[2]++;
  else if (t === 2.5) tierCounts['2.5']++;
  else if (t === 3) tierCounts[3]++;
}

const top = filtered.slice(0, 50);
return [{ json: {
  jobs: top, count: top.length, total_raw: allJobs.length,
  sources: sourceCounts, tier_counts: tierCounts,
  filter_applied: { role_families: roleFamilies, location: locationCanon || null, remote_preference: remotePref }
} }];

// Build Scorer Input v3 - reads structured resume from Supabase
const jobs = $('Experience Filter').first().json.jobs || [];
const resumeRow = $input.first().json;

let resumeSummary = 'No resume found - please run resume setup first';
if (resumeRow && resumeRow.value && typeof resumeRow.value === 'object') {
  const r = resumeRow.value;
  const parts = [];
  if (r.personal && r.personal.headline) parts.push('HEADLINE: ' + r.personal.headline);
  if (Array.isArray(r.summary_bullets) && r.summary_bullets.length) {
    parts.push('SUMMARY:\n' + r.summary_bullets.slice(0,5).map(b => '- ' + b).join('\n'));
  }
  if (Array.isArray(r.experience) && r.experience.length) {
    const expBlocks = r.experience.slice(0, 3).map(e => {
      const dates = (e.start_date || '?') + ' to ' + (e.is_current ? 'current' : (e.end_date || '?'));
      const bullets = [];
      (e.projects || []).slice(0, 2).forEach(pr => {
        if (pr.bullets) bullets.push.apply(bullets, pr.bullets.slice(0, 3));
      });
      return e.title + ' @ ' + e.company + ' (' + dates + ')'
        + (bullets.length ? '\n  ' + bullets.slice(0, 4).map(b => '- ' + b).join('\n  ') : '');
    });
    parts.push('EXPERIENCE:\n' + expBlocks.join('\n\n'));
  }
  if (Array.isArray(r.projects) && r.projects.length) {
    const projBlocks = r.projects.slice(0, 4).map(p => p.name + (p.tech ? ' [' + p.tech.slice(0, 5).join(', ') + ']' : ''));
    parts.push('PROJECTS: ' + projBlocks.join(' | '));
  }
  if (r.skills && typeof r.skills === 'object') {
    const cats = ['programming','ai_ml','data_mlops','cloud_devops'];
    const skillsList = [];
    cats.forEach(c => { if (Array.isArray(r.skills[c])) skillsList.push.apply(skillsList, r.skills[c]); });
    if (skillsList.length) parts.push('SKILLS: ' + skillsList.slice(0, 30).join(', '));
  }
  if (Array.isArray(r.education) && r.education.length) {
    parts.push('EDUCATION: ' + r.education.map(e => (e.degree || '') + ' ' + (e.field || '') + ' @ ' + (e.institution || '')).join(' | '));
  }
  resumeSummary = parts.join('\n\n').substring(0, 3500);
}

const jobBatch = jobs.map(j => ({
  job_id: j.job_id, title: j.title, company: j.company, location: j.location,
  department: j.department, url: j.url, description_snippet: j.description_snippet, source: j.source
}));
return [{ json: { master_resume_summary: resumeSummary, jobs: jobBatch } }];

const staticData = $getWorkflowStaticData('global');
const chatId = $('Extract Input').item.json.chat_id;
const rawMessage = $('Telegram Trigger').first().json.message?.text || '';
const entities = $('Route Intent').item.json.output?.entities || {};
const jobNumber = entities.job_number;
const urlMatch = rawMessage.match(/https?:\/\/[^\s]+/);
if (urlMatch) {
  const jobUrl = decodeURIComponent(urlMatch[0]);
  let company = 'unknown'; let source = 'web';
  const m = { ashby: jobUrl.match(/jobs\.ashbyhq\.com\/([^\/]+)\//), lever: jobUrl.match(/jobs\.lever\.co\/([^\/]+)\//), greenhouse: jobUrl.match(/(?:boards|job-boards)\.greenhouse\.io\/([^\/]+)\//), workday: jobUrl.match(/([^.]+)\.wd\d+\.myworkdayjobs\.com\//), workable: jobUrl.match(/apply\.workable\.com\/([^\/]+)\//) };
  for (const [src, match] of Object.entries(m)) { if (match) { company = match[1]; source = src; break; } }
  return [{ json: { chat_id: chatId, job_number: 0, direct_url: jobUrl, source, company_slug: company, greenhouse_id: null, job: { job_id: `direct-${company}-0`, title: '', company, location: '', url: jobUrl, description_snippet: '' } } }];
}
if (!jobNumber) return [{ json: { chat_id: chatId, error: 'No job number provided. Reply with a number (1-5) after a job search, or paste a job URL directly.' } }];
const lastJobs = staticData.last_jobs || {};
const job = lastJobs[jobNumber];
if (!job) return [{ json: { chat_id: chatId, error: `Job #${jobNumber} not found. Run a job search first, or paste a job URL directly.` } }];
const parts = job.job_id.split('-');
const greenhouseId = parts.pop();
const companySlug = parts.join('-');
return [{ json: { chat_id: chatId, job_number: jobNumber, company_slug: companySlug, greenhouse_id: greenhouseId, source: job.source || 'greenhouse', job } }];

const retrieveData = $('Retrieve Job').first().json;
const scrapeResult = $input.first().json;
let jobDescription = retrieveData.job?.description_snippet || '';
if (scrapeResult) {
  const md = scrapeResult.markdown || (scrapeResult.data && scrapeResult.data.markdown) || '';
  if (md && md.length > 100) jobDescription = md.substring(0, 8000);
}
const metadata = scrapeResult?.metadata || scrapeResult?.data?.metadata || {};
const job = retrieveData.job || {};
const jobTitle = job.title || metadata.title?.replace(/ \| .*$/, '').trim() || 'Unknown Role';
const company = job.company || retrieveData.company_slug || metadata.ogSiteName || 'unknown';
return [{ json: { chat_id: retrieveData.chat_id, job_number: retrieveData.job_number, job_title: jobTitle, company, company_slug: retrieveData.company_slug, location: job.location || metadata.geo_region || 'Unknown', job_url: retrieveData.direct_url || job.url || '', job_description: jobDescription, fit_score_from_digest: job.fit_score || null } }];

const fs = require('fs');
const jobCtx = $('Prepare Job Context').first().json;
let resumeText = '';
const paths = ['/home/node/.n8n-files/user-data/master_resume.txt','/data/user-data/master_resume.txt'];
for (const p of paths) { try { resumeText = fs.readFileSync(p, 'utf-8'); if (resumeText) break; } catch(e) {} }
if (!resumeText) {
  return [{ json: { ...jobCtx, resume_text: '', personal: {}, _validation_error: true, _missing_fields: ['master_resume.txt not found'], error: 'Resume not found. Send me your resume as a PDF or DOCX file and I\'ll set it up automatically. Or create user-data/master_resume.txt manually — see docs/MASTER_RESUME_GUIDE.md' } }];
}
const personal = {};
const fieldPattern = /^(name|email|phone_primary|phone_secondary|phone|linkedin|github|portfolio|location|show_location|work_authorization):\s*(.+)/gim;
let match;
while ((match = fieldPattern.exec(resumeText)) !== null) {
  const key = match[1].toLowerCase();
  const val = match[2].trim();
  if (val.startsWith('[') && val.endsWith(']')) continue;
  if (val.startsWith('#')) continue;
  personal[key] = val;
}
if (personal.phone && !personal.phone_primary) personal.phone_primary = personal.phone;
const jobLocation = (jobCtx.location || jobCtx.job_title || '').toLowerCase();
const indiaKeywords = ['india','hyderabad','bengaluru','bangalore','mumbai','pune','delhi','chennai','kolkata','indian subcontinent'];
const targetIsIndia = indiaKeywords.some(kw => jobLocation.includes(kw));
if (targetIsIndia && personal.phone_secondary) { personal.phone_display = personal.phone_secondary; } else { personal.phone_display = personal.phone_primary || personal.phone_secondary || ''; }
personal.show_location = (personal.show_location || 'false').toLowerCase() === 'true';
const required = ['name','email'];
const missing = required.filter(f => !personal[f]);
if (missing.length > 0) {
  return [{ json: { ...jobCtx, resume_text: resumeText, personal, _validation_error: true, _missing_fields: missing, error: `master_resume.txt missing: ${missing.join(', ')}. See docs/MASTER_RESUME_GUIDE.md` } }];
}
return [{ json: { ...jobCtx, resume_text: resumeText, personal, _validation_error: false } }];

const fs = require('fs');
const ctx = $('Parse Personal Info').item.json;
const seniorityOutput = $input.first().json.output || { mode: 'experienced' };
const mode = seniorityOutput.mode || 'experienced';
const skeletonMap = { fresher: '/data/templates/resume_skeleton_fresher.tex', experienced: '/data/templates/resume_skeleton_experienced.tex', senior: '/data/templates/resume_skeleton_senior.tex' };
let resumeSkeleton = '', coverSkeleton = '';
try { resumeSkeleton = fs.readFileSync(skeletonMap[mode] || skeletonMap.experienced, 'utf-8'); } catch (e) { try { resumeSkeleton = fs.readFileSync(skeletonMap.experienced, 'utf-8'); } catch (e2) {} }
try { coverSkeleton = fs.readFileSync('/data/templates/cover_skeleton.tex', 'utf-8'); } catch (e) {}
return [{ json: { ...ctx, seniority_mode: mode, total_years_experience: seniorityOutput.total_years_experience || 0, resume_skeleton: resumeSkeleton, cover_skeleton: coverSkeleton, fit_strategy: seniorityOutput.fit_strategy || 'perfect_fit', candidate_yoe: seniorityOutput.candidate_yoe || 0, jd_required_min: seniorityOutput.jd_required_min ?? null, jd_required_max: seniorityOutput.jd_required_max ?? null, jd_seniority: seniorityOutput.jd_seniority || 'unknown' } }];

const ctx = $('Load Skeletons').item.json;
const scoreOutput = $input.first().json.output || { overall_score: 5.0, recommendation: 'Caution', gaps: [], strengths: [] };
return [{ json: { ...ctx, forge_score: scoreOutput, overall_score: scoreOutput.overall_score || 5.0, recommendation: scoreOutput.recommendation || 'Caution', gaps: scoreOutput.gaps || [], strengths: scoreOutput.strengths || [], keyword_gaps: scoreOutput.keyword_gaps || [], keyword_hits: scoreOutput.keyword_hits || [] } }];

function escapeLatexText(input) {
  if (typeof input !== 'string') return '';
  return input.replace(/\\/g, '\\textbackslash{}').replace(/&/g, '\\&').replace(/%/g, '\\%').replace(/\$/g, '\\$').replace(/#/g, '\\#').replace(/_/g, '\\_').replace(/\{/g, '\\{').replace(/\}/g, '\\}').replace(/\^/g, '\\textasciicircum{}').replace(/~/g, '\\textasciitilde{}');
}
function cleanText(str) {
  if (!str) return '';
  return str.replace(/\\[a-zA-Z]+\{([^}]*)\}/g, '$1').replace(/\\[a-zA-Z]+/g, '').replace(/\$[^$]*\$/g, '').trim();
}
function extractBetweenMarkers(text, startMarker, endMarker) {
  const lines = text.replace(/\r\n/g, '\n').split('\n');
  const startIdx = lines.findIndex(l => l.trim() === startMarker);
  if (startIdx === -1) return null;
  const endIdx = lines.findIndex((l, i) => i > startIdx && l.trim() === endMarker);
  if (endIdx === -1) return null;
  return lines.slice(startIdx + 1, endIdx).join('\n').trim();
}
function wrapResumeWithSkeleton(params) {
  const { skeleton, headerLatex, contentLatex } = params;
  if (!skeleton) return '\\documentclass[letterpaper,11pt]{article}\n\\begin{document}\n' + headerLatex + '\n\n' + contentLatex + '\n\\end{document}\n';
  const lines = skeleton.replace(/\r\n/g, '\n').split('\n');
  const hs = lines.findIndex(l => l.trim() === '%%% HEADER_START');
  const he = lines.findIndex((l, i) => i > hs && l.trim() === '%%% HEADER_END');
  if (hs !== -1 && he !== -1) lines.splice(hs + 1, he - hs - 1, headerLatex.trim());
  const cs = lines.findIndex(l => l.trim() === '%%% CONTENT_START');
  const ce = lines.findIndex((l, i) => i > cs && l.trim() === '%%% CONTENT_END');
  if (cs !== -1 && ce !== -1) { lines.splice(cs + 1, ce - cs - 1, contentLatex.trim()); return lines.join('\n'); }
  const endDocIdx = lines.findIndex(l => l.includes('\\end{document}'));
  if (endDocIdx !== -1) lines.splice(endDocIdx, 0, contentLatex.trim());
  else lines.push(contentLatex.trim());
  return lines.join('\n');
}
function sanitizeResumeContentBlock(content) {
  const lines = content.replace(/\r\n/g, '\n').split('\n');
  const banned = ['\\documentclass','\\usepackage','\\begin{document}','\\end{document}','\\ResumeHeader','\\setlength','\\addtolength','\\pagestyle','\\urlstyle','\\geometry','\\begin{center}','\\end{center}','\\begin{tabularx}','\\end{tabularx}','%%% HEADER_START','%%% HEADER_END'];
  const bannedRe = new RegExp('(' + banned.map(s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') + ')');
  return lines.filter(l => !bannedRe.test(l)).join('\n').trim();
}
function normalizeLatexForPdflatex(input) {
  if (!input) return input;
  let s = input.replace(/\r\n/g, '\n');
  s = s.replace(/[\u201C\u201D]/g, '"').replace(/[\u2018\u2019]/g, "'").replace(/\u2026/g, '...').replace(/[\u2013\u2014]/g, '--').replace(/\u00A0/g, ' ');
  s = s.replace(/\u20B9/g, 'INR ').replace(/\u20AC/g, 'EUR ').replace(/\u00A3/g, 'GBP ').replace(/(?<!\\)\$/g, '\\$');
  s = s.replace(/[^\x09\x0A\x0D\x20-\x7E]/g, '');
  return s;
}
const resumeJson = $input.first().json.output || $input.first().json;
const ctx = $('Prepare Apply Context').item.json;
const skeleton = ctx.resume_skeleton;
const personal = ctx.personal || {};
const seniorityOutput = $('SeniorityDetector').item.json.output || {};
function buildPortfolioLine(p) {
  if (!p.portfolio) return '';
  const url = p.portfolio.startsWith('http') ? p.portfolio : 'https://' + p.portfolio;
  const display = p.portfolio.replace(/^https?:\/\//, '');
  return ' $|$\n    \\href{' + url + '}{\\underline{' + escapeLatexText(display) + '}}';
}
function buildGithubLine(p, mode) {
  if (mode === 'senior' || !p.github) return '';
  const url = p.github.startsWith('http') ? p.github : 'https://' + p.github;
  const display = p.github.replace(/^https?:\/\//, '');
  return ' $|$\n    \\href{' + url + '}{\\underline{' + escapeLatexText(display) + '}}';
}
function buildLocationLine(p) {
  if (!p.show_location || !p.location) return '';
  return ' $|$\n    ' + escapeLatexText(p.location);
}
const headerTemplate = extractBetweenMarkers(skeleton, '%%% HEADER_START', '%%% HEADER_END') || '';
const seniorityMode = ctx.seniority_mode || seniorityOutput.mode || 'experienced';
const headerLatex = headerTemplate.replace('{{NAME}}', escapeLatexText(personal.name || 'Candidate')).replace('{{PHONE}}', escapeLatexText(personal.phone_display || personal.phone_primary || '')).replace('{{EMAIL}}', personal.email || '').replace('{{LINKEDIN}}', personal.linkedin || '').replace('{{PORTFOLIO_LINE}}', buildPortfolioLine(personal)).replace('{{GITHUB_LINE}}', buildGithubLine(personal, seniorityMode)).replace('{{LOCATION_LINE}}', buildLocationLine(personal));
const sections = resumeJson.sections || [];
const contentParts = [];
for (const section of sections) {
  const heading = section.heading || '';
  const items = section.items || [];
  if (heading === 'Skills' || heading === 'Technical Skills') {
    contentParts.push('\\section{Technical Skills}');
    contentParts.push('\\resumeSubHeadingListStart');
    for (const item of items) { if (item.type === 'skill_line') contentParts.push('  \\resumeSkillLine{' + escapeLatexText(item.category || '') + '}{' + escapeLatexText(item.skills || '') + '}'); }
    contentParts.push('\\resumeSubHeadingListEnd');
  } else if (heading === 'Education') {
    contentParts.push('\\section{Education}');
    contentParts.push('\\resumeSubHeadingListStart');
    for (const item of items) {
      if (item.type === 'education') {
        const degree = [item.degree, item.major].filter(Boolean).join(' in ');
        contentParts.push('  \\resumeSubheading{' + escapeLatexText(item.institution || '') + '}{' + escapeLatexText(item.location || '') + '}{' + escapeLatexText(degree) + '}{' + escapeLatexText(item.dates || '') + '}');
        if (item.gpa) contentParts.push('  \\resumeItem{GPA: ' + escapeLatexText(item.gpa) + '}');
        if (item.coursework) contentParts.push('  \\resumeItem{Coursework: ' + escapeLatexText(item.coursework) + '}');
      }
    }
    contentParts.push('\\resumeSubHeadingListEnd');
  } else if (heading === 'Experience') {
    contentParts.push('\\section{Experience}');
    contentParts.push('\\resumeSubHeadingListStart');
    for (const item of items) {
      if (item.type === 'role') {
        contentParts.push('  \\resumeSubheading{' + escapeLatexText(item.role || '') + '}{' + escapeLatexText(item.dates || '') + '}{' + escapeLatexText(item.company || '') + '}{' + escapeLatexText(item.location || '') + '}');
        if (item.bullets && item.bullets.length > 0) {
          contentParts.push('  \\resumeItemListStart');
          for (const bullet of item.bullets) {
            const rawKw = cleanText(bullet.keyword || ''); const rawTxt = cleanText(bullet.text || '');
            const kw = rawKw ? '\\textbf{' + escapeLatexText(rawKw) + ':} ' : '';
            contentParts.push('    \\resumeItem{' + kw + escapeLatexText(rawTxt) + '}');
          }
          contentParts.push('  \\resumeItemListEnd');
        }
      }
    }
    contentParts.push('\\resumeSubHeadingListEnd');
  } else if (heading === 'Projects') {
    contentParts.push('\\section{Projects}');
    contentParts.push('\\resumeSubHeadingListStart');
    for (const item of items) {
      if (item.type === 'project') {
        const techStr = item.tech ? ' $|$ ' + escapeLatexText(item.tech) : '';
        contentParts.push('  \\resumeProjectHeading{\\textbf{' + escapeLatexText(item.name || '') + '}' + techStr + '}{' + (item.url ? escapeLatexText(item.url) : '') + '}');
        if (item.bullets && item.bullets.length > 0) {
          contentParts.push('  \\resumeItemListStart');
          for (const bullet of item.bullets) {
            const rawKw = cleanText(bullet.keyword || ''); const rawTxt = cleanText(bullet.text || '');
            const kw = rawKw ? '\\textbf{' + escapeLatexText(rawKw) + ':} ' : '';
            contentParts.push('    \\resumeItem{' + kw + escapeLatexText(rawTxt) + '}');
          }
          contentParts.push('  \\resumeItemListEnd');
        }
      }
    }
    contentParts.push('\\resumeSubHeadingListEnd');
  }
}
const contentLatex = contentParts.join('\n');
const sanitized = sanitizeResumeContentBlock(contentLatex);
const fullLatex = wrapResumeWithSkeleton({ skeleton, headerLatex, contentLatex: sanitized });
const normalized = normalizeLatexForPdflatex(fullLatex);
return [{ json: { latex: normalized, chat_id: ctx.chat_id, job_title: ctx.job_title, company: ctx.company } }];

function escapeLatexText(input) {
  if (typeof input !== 'string') return '';
  return input.replace(/\\/g, '\\textbackslash{}').replace(/&/g, '\\&').replace(/%/g, '\\%').replace(/\$/g, '\\$').replace(/#/g, '\\#').replace(/_/g, '\\_').replace(/\{/g, '\\{').replace(/\}/g, '\\}').replace(/\^/g, '\\textasciicircum{}').replace(/~/g, '\\textasciitilde{}');
}
function cleanText(str) {
  if (!str) return '';
  return str.replace(/\\[a-zA-Z]+\{([^}]*)\}/g, '$1').replace(/\\[a-zA-Z]+/g, '').replace(/\$[^$]*\$/g, '').trim();
}
function wrapResumeWithSkeleton(params) {
  const { skeleton, headerLatex, contentLatex } = params;
  if (!skeleton) return contentLatex;
  const lines = skeleton.replace(/\r\n/g, '\n').split('\n');
  const hs = lines.findIndex(l => l.trim() === '%%% HEADER_START');
  const he = lines.findIndex((l, i) => i > hs && l.trim() === '%%% HEADER_END');
  if (hs !== -1 && he !== -1) lines.splice(hs + 1, he - hs - 1, headerLatex.trim());
  const cs = lines.findIndex(l => l.trim() === '%%% CONTENT_START');
  const ce = lines.findIndex((l, i) => i > cs && l.trim() === '%%% CONTENT_END');
  if (cs !== -1 && ce !== -1) { lines.splice(cs + 1, ce - cs - 1, contentLatex.trim()); return lines.join('\n'); }
  const endDocIdx = lines.findIndex(l => l.includes('\\end{document}'));
  if (endDocIdx !== -1) lines.splice(endDocIdx, 0, contentLatex.trim());
  else lines.push(contentLatex.trim());
  return lines.join('\n');
}
function normalizeLatexForPdflatex(input) {
