const sd = $getWorkflowStaticData('global');
const resumeForgeOutput = $('ResumeForge').first().json.output || {};
const forgeScoreOutput = $('ForgeScore').first().json.output || {};
const seniorityOutput = $('SeniorityDetector').first().json.output || {};
const jdCtx = $('Prepare Job Context').first().json;
sd.last_resume_json = resumeForgeOutput.sections || resumeForgeOutput || {};
sd.last_jd = jdCtx.job_description || '';
sd.last_fit_strategy = seniorityOutput.fit_strategy || 'perfect_fit';
sd.last_keyword_gaps = forgeScoreOutput.keyword_gaps || [];
return $input.all();

// Build You.com Queries v2 — LLM creativity + deterministic ATS coverage
// We keep the LLM's queries (good for variants we wouldn't think of) and
// ALWAYS add a fixed set of site-targeted ATS queries built from
// role_families + location, so You.com is never trusted to do domain control
// on its own. Output: deduped list, capped at 6 queries.

const ctx = $('Parse Expand Query').first().json;
const llmQueries = ctx.youcom_queries || [];
const roles = ctx.role_families || [];

if (!roles.length && !llmQueries.length) {
  return [{ json: { _disabled: true, source: 'youcom', reason: 'No queries and no role_families' } }];
}

const top = roles.slice(0, 2);
const loc = (ctx.location_canonical || '').split(',')[0].trim();
const locPart = loc ? ' "' + loc + '"' : '';
const role0 = top[0] || '';
const role1 = top[1] || top[0] || '';

const deterministic = role0 ? [
  'site:boards.greenhouse.io "' + role0 + '"' + locPart,
  'site:jobs.lever.co "' + role0 + '"' + locPart,
  '(site:jobs.ashbyhq.com OR site:apply.workable.com) "' + role0 + '"' + locPart,
  '(site:myworkdayjobs.com OR site:jobs.smartrecruiters.com) "' + role1 + '"' + locPart,
] : [];

const all = [...llmQueries, ...deterministic];
const seen = new Set();
const queries = [];
for (const q of all) {
  if (!q) continue;
  const k = String(q).toLowerCase().trim();
  if (k && !seen.has(k)) { seen.add(k); queries.push(q); }
}

return queries.slice(0, 6).map(q => ({ json: { _disabled: false, query: q } }));

// --- URL Tier Classifier ---------------------------------------------------
// Tiers: 1 = direct ATS, 2 = curated boards, 2.5 = unknown career page,
//        3 = general aggregator, 4 = unknown / probably not a job
function classifyUrlTier(url) {
  if (!url) return { tier: 4, label: 'invalid' };
  const u = url.toLowerCase();
  // TIER 1 — Direct ATS platforms
  if (/(?:boards|job-boards)\.greenhouse\.io/.test(u)) return { tier: 1, label: 'ats:greenhouse' };
  if (/jobs\.lever\.co/.test(u)) return { tier: 1, label: 'ats:lever' };
  if (/jobs\.ashbyhq\.com/.test(u)) return { tier: 1, label: 'ats:ashby' };
  if (/[\w-]+\.wd\d+\.myworkdayjobs\.com/.test(u)) return { tier: 1, label: 'ats:workday' };
  if (/apply\.workable\.com/.test(u)) return { tier: 1, label: 'ats:workable' };
  if (/jobs\.smartrecruiters\.com/.test(u)) return { tier: 1, label: 'ats:smartrecruiters' };
  if (/workatastartup\.com\/jobs\//.test(u)) return { tier: 1, label: 'ats:yc' };
  if (/[\w-]+\.recruitee\.com/.test(u)) return { tier: 1, label: 'ats:recruitee' };
  if (/[\w-]+\.personio\.(com|de)/.test(u)) return { tier: 1, label: 'ats:personio' };
  if (/[\w-]+\.bamboohr\.com/.test(u)) return { tier: 1, label: 'ats:bamboohr' };
  if (/[\w-]+\.jobvite\.com/.test(u)) return { tier: 1, label: 'ats:jobvite' };
  if (/careers-[\w-]+\.icims\.com/.test(u)) return { tier: 1, label: 'ats:icims' };
  if (/[\w-]+\.taleo\.net/.test(u)) return { tier: 1, label: 'ats:taleo' };
  if (/successfactors\.(com|eu)/.test(u)) return { tier: 1, label: 'ats:successfactors' };
  if (/[\w-]+\.eightfold\.ai/.test(u)) return { tier: 1, label: 'ats:eightfold' };
  // TIER 2 — Curated remote/aggregator boards
  if (/weworkremotely\.com\/(remote-jobs|listings)\//.test(u)) return { tier: 2, label: 'curated:wwr' };
  if (/remoteok\.(com|io)/.test(u)) return { tier: 2, label: 'curated:remoteok' };
  if (/himalayas\.app\/jobs\//.test(u)) return { tier: 2, label: 'curated:himalayas' };
  if (/remotive\.(com|io)\/(jobs|remote-jobs)\//.test(u)) return { tier: 2, label: 'curated:remotive' };
  if (/jobicy\.com/.test(u)) return { tier: 2, label: 'curated:jobicy' };
  if (/wellfound\.com\/jobs\//.test(u)) return { tier: 2, label: 'curated:wellfound' };
  if (/arbeitnow\.com\/jobs\//.test(u)) return { tier: 2, label: 'curated:arbeitnow' };
  if (/ai-jobs\.net\/job\//.test(u)) return { tier: 2, label: 'curated:aijobs' };
  if (/builtin(nyc|sf|la|chicago|seattle|boston|austin)?\.com\/job\//.test(u)) return { tier: 2, label: 'curated:builtin' };
  // TIER 3 — General web aggregators (often listings pages, low signal)
  if (/linkedin\.com/.test(u)) return { tier: 3, label: 'aggregator:linkedin' };
  if (/indeed\.com/.test(u)) return { tier: 3, label: 'aggregator:indeed' };
  if (/glassdoor\.com/.test(u)) return { tier: 3, label: 'aggregator:glassdoor' };
  if (/ziprecruiter\.com/.test(u)) return { tier: 3, label: 'aggregator:ziprecruiter' };
  if (/dice\.com/.test(u)) return { tier: 3, label: 'aggregator:dice' };
  if (/monster\.com/.test(u)) return { tier: 3, label: 'aggregator:monster' };
  if (/simplyhired\.com/.test(u)) return { tier: 3, label: 'aggregator:simplyhired' };
  if (/careerbuilder\.com/.test(u)) return { tier: 3, label: 'aggregator:careerbuilder' };
  if (/snagajob\.com/.test(u)) return { tier: 3, label: 'aggregator:snagajob' };
  if (/theladders\.com/.test(u)) return { tier: 3, label: 'aggregator:theladders' };
  if (/jora\.com/.test(u)) return { tier: 3, label: 'aggregator:jora' };
  if (/talent\.com/.test(u)) return { tier: 3, label: 'aggregator:talent' };
  if (/jobs2careers\.com/.test(u)) return { tier: 3, label: 'aggregator:jobs2careers' };
  // TIER 2.5 — Plausible career page on unrecognized domain
  if (/^https?:\/\/(careers|jobs|apply|hiring|talent|work|join)\.[\w-]+\.[\w.]+/.test(u)) {
    return { tier: 2.5, label: 'career:subdomain' };
  }
  if (/\/(careers|jobs|join-us|join_us|apply|positions|openings|opportunities|vacancies|hiring|work-with-us)\//.test(u)) {
    return { tier: 2.5, label: 'career:path' };
  }
  // TIER 4 — Anything else
  return { tier: 4, label: 'unknown' };
}

// Normalize You.com Search output → standard job object
// Native node shape: { results: { web: [...], snippets: [...] } }

const hits = $input.all();
const allJobs = [];

function extractCompanyFromUrl(url) {
  let m;
  if ((m = url.match(/(?:boards|job-boards)\.greenhouse\.io\/(?:embed\/job_board\?for=)?([^/?&#]+)/))) return m[1];
  if ((m = url.match(/jobs\.lever\.co\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/jobs\.ashbyhq\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/([^.\/]+)\.wd\d+\.myworkdayjobs\.com/))) return m[1];
  if ((m = url.match(/apply\.workable\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/jobs\.smartrecruiters\.com\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/workatastartup\.com\/jobs\/\d+\/[^?#]*?-at-([^/?#]+)/))) return m[1];
  if ((m = url.match(/wellfound\.com\/jobs\/[^/]*?-at-([^/?#]+)/))) return m[1];
  if ((m = url.match(/wellfound\.com\/company\/([^/?#]+)/))) return m[1];
  if ((m = url.match(/(?:weworkremotely|remoteok|himalayas|remotive|jobicy|arbeitnow)\./))) return url.match(/(?:weworkremotely|remoteok|himalayas|remotive|jobicy|arbeitnow)/)[0];
  if ((m = url.match(/^https?:\/\/(?:www\.)?([^.]+)\./))) return m[1];
  return 'unknown';
}

function extractLocationFromText(text) {
  let m;
  if ((m = text.match(/(?:in|at|–|-|·|—)\s*([A-Z][\w\s]+,\s*[A-Z]{2,})/))) return m[1].trim();
  if ((m = text.match(/\b(New York|San Francisco|Seattle|Boston|Austin|Chicago|Los Angeles|Remote)\b/i))) return m[1];
  return '';
}

for (const item of hits) {
  if (item.json._disabled) continue;

  const results = item.json.results;
  let entries = [];
  if (Array.isArray(results)) entries = results;
  else if (results && Array.isArray(results.web)) entries = results.web;
  else if (Array.isArray(item.json.hits)) entries = item.json.hits;
  else if (Array.isArray(item.json.organic)) entries = item.json.organic;
  else if (Array.isArray(item.json.web)) entries = item.json.web;

  for (const r of entries) {
    const url = r.url || r.link || '';
    if (!url) continue;
    const title = r.title || '';
    const desc = r.description || r.snippet || (r.snippets || []).join(' ') || '';
    const company = extractCompanyFromUrl(url);
    const location = extractLocationFromText(title) || extractLocationFromText(desc) || '';

    const __tier = classifyUrlTier(url);
    allJobs.push({
      job_id: `youcom-${company}-${allJobs.length}`,
      title,
      company,
      location,
      department: '',
      url,
      description_snippet: desc.substring(0, 500),
      updated_at: r.page_age || r.published_date || '',
      source: 'youcom',
      source_tier: __tier.tier,
      tier_label: __tier.label
    });
  }
}

return [{ json: { jobs: allJobs, source: 'youcom', count: allJobs.length } }];

// Build Serper Queries v2 — LLM creativity + deterministic ATS coverage
// Same idea as Build You.com Queries, with after:YYYY-MM-DD baked in for
// every deterministic query so freshness is guaranteed regardless of what
// the LLM produced. Capped at 4 to respect the Serper free tier.

const ctx = $('Parse Expand Query').first().json;
const llmQueries = ctx.serper_queries || [];
const roles = ctx.role_families || [];

if (!roles.length && !llmQueries.length) {
  return [{ json: { _disabled: true, source: 'serper', reason: 'No queries and no role_families' } }];
}

const top = roles.slice(0, 2);
const loc = (ctx.location_canonical || '').split(',')[0].trim();
const locPart = loc ? ' "' + loc + '"' : '';
const role0 = top[0] || '';
const role1 = top[1] || top[0] || '';

const freshness = ctx.freshness || 'qdr:w';
const daysBack = { 'qdr:h': 1, 'qdr:d': 1, 'qdr:w': 7, 'qdr:m': 30, 'qdr:y': 365 }[freshness] || 7;
const sinceDate = new Date(Date.now() - daysBack * 86400000).toISOString().split('T')[0];

const deterministic = role0 ? [
  '(site:boards.greenhouse.io OR site:jobs.lever.co) "' + role0 + '"' + locPart + ' after:' + sinceDate,
  '(site:jobs.ashbyhq.com OR site:myworkdayjobs.com) "' + role0 + '"' + locPart + ' after:' + sinceDate,
  '(site:apply.workable.com OR site:jobs.smartrecruiters.com) "' + role1 + '"' + locPart + ' after:' + sinceDate,
] : [];

const all = [...llmQueries, ...deterministic];
const seen = new Set();
const queries = [];
for (const q of all) {
  if (!q) continue;
  const k = String(q).toLowerCase().trim();
  if (k && !seen.has(k)) { seen.add(k); queries.push(q); }
}

return queries.slice(0, 4).map(q => ({ json: { _disabled: false, query: q } }));

// --- URL Tier Classifier ---------------------------------------------------
// Tiers: 1 = direct ATS, 2 = curated boards, 2.5 = unknown career page,
