parameters.jsCode:
// Process Normalized Resume — validate, attach metadata, render preview
const out = $input.first().json;
let parsed = null;
try {
  if (out && out.output) {
    parsed = typeof out.output === 'string' ? JSON.parse(out.output) : out.output;
  } else {
    parsed = typeof out === 'string' ? JSON.parse(out) : out;
  }
} catch(e) {
  return [{ json: { _error: 'Failed to parse normalizer output: ' + e.message, _raw: out } }];
}

// Basic shape validation
const required = ['personal','experience','projects','education','skills'];
const missing = required.filter(k => !parsed[k]);
if (missing.length) {
  return [{ json: { _error: 'Normalizer output missing required fields: ' + missing.join(', '), _raw: parsed } }];
}

// Attach metadata
const now = new Date().toISOString();
parsed.metadata = {
  created_at: now,
  updated_at: now,
  source_model: 'anthropic/claude-sonnet-4.6',
  ingestion_version: 1
};
parsed.schema_version = parsed.schema_version || 1;

// Get chat_id from upstream — preserve through the chain
const chatId = $('Extract Input').first().json.chat_id;

return [{ json: {
  chat_id: chatId,
  resume_doc: parsed,
  _meta: { processed_at: now }
} }];

// Build Preview Message — render structured doc as readable Telegram + inline keyboard
const upstream = $input.first().json;
const r = upstream.resume_doc;
const chatId = upstream.chat_id;

if (!r) {
  return [{ json: { chat_id: chatId, message_text: '⚠️ Could not parse resume. Please try again or paste the original text.', reply_markup: null } }];
}

const p = r.personal || {};
const expCount = (r.experience || []).length;
const projCount = (r.projects || []).length;
const eduCount = (r.education || []).length;
const skillCats = Object.keys(r.skills || {}).length;
const hackathons = ((r.achievements || {}).hackathon_wins || []).length;

const primaryEmail = (p.emails || []).find(e => e.primary)?.address || (p.emails || [])[0]?.address || '—';
const primaryPhone = (p.phones || []).find(ph => ph.primary)?.number || (p.phones || [])[0]?.number || '—';
const primaryLoc = (p.locations || []).find(l => l.primary) || (p.locations || [])[0];
const locStr = primaryLoc ? `${primaryLoc.city}, ${primaryLoc.region}` : '—';

let msg = '📄 *Resume Parsed — Preview*\n\n';
msg += `*Name:* ${p.name || '—'}\n`;
if (p.headline) msg += `*Headline:* ${p.headline.length > 100 ? p.headline.slice(0,97) + '...' : p.headline}\n`;
msg += `*Email:* ${primaryEmail}\n`;
msg += `*Phone:* ${primaryPhone}\n`;
msg += `*Location:* ${locStr}\n`;
msg += '\n*Counts:*\n';
msg += `  • Experience entries: ${expCount}\n`;
msg += `  • Personal projects: ${projCount}\n`;
msg += `  • Education entries: ${eduCount}\n`;
msg += `  • Skill categories: ${skillCats}\n`;
if (hackathons) msg += `  • Hackathon wins: ${hackathons}\n`;

if (expCount > 0) {
  msg += '\n*Most recent role:*\n';
  const e0 = r.experience[0];
  msg += `  ${e0.title || '?'} @ ${e0.company || '?'}\n`;
  msg += `  ${e0.start_date || '?'} → ${e0.is_current ? 'current' : (e0.end_date || '?')}\n`;
}

msg += '\n_Tap a button below:_';

const reply_markup = {
  inline_keyboard: [
    [
      { text: '✅ Looks good — save it', callback_data: 'resume:apply' },
      { text: '❌ Cancel', callback_data: 'resume:cancel' }
    ],
    [
      { text: '✏️ Re-parse (be more careful)', callback_data: 'resume:redo' }
    ]
  ]
};

return [{ json: {
  chat_id: chatId,
  message_text: msg,
  reply_markup: JSON.stringify(reply_markup),
  resume_doc: r
} }];

// Prep Save Pending Resume body — assembles the Supabase upsert row
const upstream = $input.first().json;
const chatId = upstream.chat_id;
const now = new Date().toISOString();
return [{ json: {
  chat_id: chatId,
  upsert_row: {
    id: 'pending_edit:' + chatId,
    scope: 'pending',
    key: 'resume_setup_' + chatId,
    value: { resume_doc: upstream.resume_doc, created_at: now, ttl_seconds: 600 }
  },
  message_text: upstream.message_text,
  reply_markup: upstream.reply_markup
} }];
